INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل عملي وشامل للمزارعين حول صيانة شريط التيب أثناء زراعة البطيخ لضمان أفضل النتائج. تعرف على التقنيات الحديثة وأدوات الصيانة المناسبة لبيئتك.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
