INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Discover the optimal okra seed rate per hectare. This comprehensive guide covers planting densities, spacing, and AFP-based strategies to maximize irrigation efficiency and crop yield.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
