INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима</h2><p>Оҳура яке аз бардакҳои муҳим ва маъмул дар Ирон мебошад, ки аз ҷиҳати тиҷоратӣ ва истеъмолоти дохилӣ мақоми хос дорад. Яке аз саволҳои маъмули деҳқонон миқдори дақиқи бобуи зарурӣ барои ҳар гектар замин аст. Ҳисобкунии дурусти ин миқдор таъсири мустақимро ба харҷҳо, рушди ҷишот ва дар ниҳоят миқдори ҳосилнокӣ мерасонад. Дар ин мақола, бо тафсилоти пурра ба баррасии омилҳои таъсиррасон ба <strong>миқдори бобуи оҳура дар гектар</strong> меоярӣм ва роҳҳои амалӣ барои идоракунии он пешниҳод мекунем. Фаҳмиши амиқ аз ин раванд на танҳо ба кам кардани харҷҳои ибтидоӣ кӯмак мерасонад, балки бо беҳтарсозии ҷойгиршавии буттаҳо, сифати маҳсули ниҳоиро низ баланд мебардорад. Бинобар ин, диққат ба тафсилоти техникии нигоҳдорӣ ва обнокӣ қадами муҳим барои ҳар деҳқони муваффақ аст, ки дар ҷустуҷӯи баҳрамандии иқтисодии бағи худ мебошад.</p><h2>Омилҳои таъсиррасон ба муайян кардани миқдори бобу</h2><p>Муайян кардани миқдори бобуи оҳура дар гектар танҳо як формулаи содда нест, балки маҷмӯи як қатор тағйирёбандаҳо аст, ки бояд бо дақиқӣ дар назар гирифта шаванд. Баъзеи асосии ин омилҳо намуди навиди оҳура, шартҳои иқлимии минтақа, сифати бобу ва усулҳои нигоҳдориро дар бар мегирад. Инчунин, намуди хок ва миқдори боронбории минтақа низ ба муайян кардани зичии мувофиқи нигоҳдорӣ таъсир мерасонанд. Дар хокҳои сабук, одатан имкони нигоҳдории зичтар вуҷуд дорад, зеро суръати рушди решаҳо дар ин намуди хокҳо бештар аст. Аз тарафи дигар, дар минтақаҳо, ки тобистони хеле гарм ва хушк доранд, нигоҳ доштани таркӯбии хок аҳамияти дугона дорад ва ин ба тартиб додани фосилаи нигоҳдориро талаб мекунад.</p><ul><li><strong>Намуди навид:</strong> Навидҳои пурпоя ва донандоз одатан ба зичии бобуи камтар ниёз доранд. Навидҳои сабзӣ бо рушди тезтар шояд барои мувозинати рушди гӯбук ва барг ба фазои бештар ниёз дошта бошанд.</li><li><strong>Шароитҳои обҳушшо:</strong> Дар минтақаҳои гармтар, фосилаи зичтар метавонад ба нақси беҳтар кӯмак карда, аз кулофии бастӣ ба сабаби гармии шадид пешгирӣ намояд.</li><li><strong>Сифати бастӣ:</strong> Дараҷаи ҳассосӣ ва қобилияти бурунӣ бастӣ таъсири мустақим ба шумораи зарбати лозима меорад. Бастие, ки дарсади буруниши баланд доранд, маънои онро дорад, ки барои расидан ба зичии мақсаднок бастии камтар лозим аст.</li></ul><p>Барои интихоби методҳои такӣ бар асоси принсипҳои илмӣ, омӯзиши сарчашмаҳои боварӣбахш ба монанди риёсномаи умумии китоби кабӯстарокии маъмӣ тавсия мешавад, зеро онҳо мувофиқати базебо бо китобии бамия доранд, зеро ҳарду гиёҳ дар як оила ҷойгиранда ва ниёзҳои монанд доранд.</p><h3>Фосила байни ҷазираҳо ва даромадҳо</h3><p>Яке аз муҳимтарин мавзӯъҳо дар муайян кардани <strong>миқдори бастии бамия дар ҳектар</strong>муайянку масофаҳои ғарсу. Мувоҷиби стандарти бум, масофа байни ғарсаҳо бояд тақрибан аз 2 то 2.5 метр ва масофа дохили ғарсаҳо вобаста ба навъи навис аз 50 то 80 сантиметр бошад. Ин муайяншавии масофаҳо имкон медиҳад, ки растаниҳо фазои кофӣ барои афзоиши реша ва дарахтрак дошта бошанд ва рақобатро барои захираҳо пешгирӣ кунанд. Идоракунии дурусти ин масофаҳо калиди асосӣ барои ба даст овардани ҳосили яксон ва сифатнок аст. Агар масофаи дохили ғарса кам бошад, буттаҳо ғарбуни ҳамдигарро мегиранд ва дар муқобили бемориҳои қарзоӣ ҳассостар мешаванд. Дар бархиф, масофаи зиёдатӣ боиси он мегардад, ки буттаҳо заиф боқӣ мемонанд ва аз имконияти истеҳсолии худ истифода набаранд.</p><table><thead><tr><th>Масофа байни ғарсаҳо</th><th>Масофа дохили ғарсаҳо</th><th>Шумораи буттаҳо дар як гектар</th><th>Усули ғарс</th></tr></thead><tbody><tr><td>2.0 метр</td><td>50 сантиметр</td><td>10,000 бутта</td><td>Киштии зич</td></tr><tr><td>2,5 метр</td><td>80 см</td><td>5000 намоишҳо</td><td>Киштии нозук</td></tr></tbody></table><h2>Мутобиқ кардан бо системаи обори қатрагунон ва лентаи тап</h2><p>Истифодаи системаҳои обори қатрагунон ё лентаи тап дар кишти катони, ғайр аз сарфнокии истеъмоли об, ба ҷойгиркунии намоишҳо ва дар натиҷа ба миқдори истифодаи бобӯз таъсир мерасонад. Дар ин роҳ, лентаи тап маҳз дар фосилаи намоишҳои катони ҷойгир мешавад ва ба расониш баробари об ва моддаҳои ғизоӣ ба решаҳо мусоидат менамояд. Мулоҳизаи дақиқи фосилаи кишт бо хатҳои обори, аз ҷамъоянии намии заруратар байни намоишҳо пешгирӣ мекунад ва муҳитро барои рушди бемориҳои решаӣ номуносиб мегардонад. Ин системавӣ будан дар кишт, имконот медиҳад, ки деҳқон аз бобӯз самараноктар истифода барад ва аз хароҷоти иловагии бобӯзи зиёд дур монад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-بامیه-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر بامیه در هکتار: راهنمای جامع - تصویر 1"/><figcaption>суръати бобӯз дар гектар ҳосили катони</figcaption></figure><p>Барои истифодаи беҳтарини ин система, омӯзиши фарқияти нӯҳияҳои ҷунбонӣ (stripe tillage) метавонад кордору бошад. Дар баъзе ҳолатҳо, мувофиқ кардан бо роҳнамои обкорӣ барои нақшаи самъоии 90-то низ ба барномаҳои вақти обкорӣ кӯмак мекунад, зеро ин навъ системаҳо шакли мунтазами обкорӣ доранд, ки бо эҳтиёҷоти баргул (cotton) мутобиқ аст.</p><h2>Ҳисобкунии амалии миқдори тоҷриба (биз) дар гектар</h2><p>Барои ҳисобкунии дақиқ <strong>миқдори тоҷрибаи баргул (биз) дар гектар</strong>, ин марҳилаҳоро иҷро кунед:</p><ol><li>Масоҳати замини интихобшударо бо метр чен кунед.</li><li>Фосилаи байнириб ва дарунрибро вобаста ба шароити иқлим ва навъи намуд муайян кунед.</li><li>Шумораи зарурии нишастҳоро ҳисоб кунед: (паҳии замин / фосилаи байнириб) × (дарозии замин / фосилаи дарунриб).</li><li>Миқдори бунёдро бар асоси вазни ҳар дона ва фоизи навиданӣ баррасӣ кунед.</li></ol><p>Ба миёна, истеъмолоти бунъар барои ҳар гектари боми тақрибан аз 25 то 40 килограмм аст, гарчанде ки ин рақам вобаста ба намунаи нахӯд метавонад гуногун бошад. Барои муқоиса бо дигар растаниҳо, омӯзиши мавзӯъҳое, ба монанди миқдори бунъари пиёз дар гектар, метавонад назареро дар бораи фарқияти зичии ғармошӣ беҳтар созед. Инчунин, дарк аз омилҳое, ки ба ҳосили чав дар як гектар таъсир мерасонанд, ба деҳқон кӯмак мекунад, то аз принсипҳои идоракунии манбаъҳо дар маҳсулоти гуногун истифода барад ва усулҳои интиқоли дониш байни парвозҳои гуногунро барқарор созад. Ин диди системӣ ба идоракунии деҳис, боиси иншояд, ки бунъари боми ҳамчун сармоягузории беҳтарин баррасӣ шавад, на танҳо як хароҷот.</p><h2>Нуктаҳои асосӣ ва амалӣ</h2><ul><li><strong>Синҷиши навиданӣ:</strong> Пеш аз харидани бунъар, синҷиши навиданиро анҷом диҳед, то фоизи самараро донед. Харидани бунъар аз брейндҳе, ки гузориши санҷиши бунъарро пешниҳор мекунанд, хатари ғармоширо кам мекунад.</li><li><strong>Омодагии заминаи ғармошӣ:</strong> Барои ҷойгиршавии беҳтаршавии решаҳо аз заминаи нарм ва мувофиқ истифода баред. Ободони чуқур ва намоиши сатҳии замина ба дахолати беҳтаршавии реша ва ҷабби зудтарини об кӯмак мекунад.</li><li><strong>Ғармоши дастӣ ё механикӣ:</strong> Интихоби усули бунёди мувофиқ ба дақиқии масофагузорӣ ва дар натиҷа зичии бунёд таъсир мерасонад. Бунёди механикӣ бо таҷҳизоти муосир якхонаии бешаро ба вуҷуд меорад.</li></ul><h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2><p><strong>Савол 1: Беҳтарин вақти бунёди бамиҳ дар Тоҷикистан чист?</strong><br>Одатан аз миёнаҳои баҳор то оғози тобистон. Вобаста ба минтақа ва ҳарорати ҳаво, бунёдшавиро то миёнаҳои тобистон низ метавон идома дод, ба шарти он ки обирӣ мунтазам бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-بامیه-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر بامیه در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Норми ҷамъоварии бамиҳ дар гектар</figcaption></figure><p><strong>Савол 2: Оё бамиҳ барои хокҳои вазнин мувофиқ аст?</strong><br>Бале, вале беҳтар аст, ки ҷӯраёбии мувофиқ бошад. Навбузидани бамиҳ дар қабатҳои сабттар беҳтар аст, вале дар хокҳои вазнин бо идоракунии дурусти оборӣ низ бунёд кардан мумкин аст.</p><p><strong>Савол 3: Оё масофаи бунёд ба миқдори дана дар ҳар биря таъсир мерасонад?</strong><br>Бале, кортиши ғализи бонбандӣ метавонад ба тақсимоти манбаъҳо ва ҳосил одаби хурдтар оварда расонад. Ҳоло, дар муқоиса бо корт ғализи бонбандӣ, одатан одаби калонтар ва яксон ҳосил мешавад.</p><p><strong>Савол 4: Барои ҳар як кӯлаи бамия чӣ қадар об лозим аст?</strong><br>Вобаста ба иқлим ва навъи хок, аммо одатан 10 то 15 литр об дар ҳар рӯзи абшорӣ кофист. Истифодаи системаи абшории қатрагӣ метавонад ин истифоро мукаммал кунад ва аз пардонии об пешгирӣ намояд.</p><p><strong>Савол 5: Чӣ тавр бо корт ғализи бонбандӣ метавонам ҳаҷми бадарро кам намоям?</strong><br>Бо афзудани фосилаи дароми рӯ, шумораи кӯлаҳо кам мешавад ва дар натиҷа миқдори бадари зарурӣ камтар мешавад. Ин усул дар баъзе шароити иқлимӣ метавонад самаранок бошад, махсусан дар минтақаҳои бисёр намнок.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-بامیه-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر بامیه در هکتار: راهنمای جامع - تصویر 3"/><figcaption>Мизоби бадар дар гектар барои бамия</figcaption></figure><h2>Хулоса</h2><p>Муайянкунии дақиқ <strong>Миқдори бории қуinoa дар ҳектар</strong> Ин як раванди бисёрмарҳила аст, ки ба диққат ба муҳимоти чун намуди навъ, шароити иқлимӣ, масофаи шинонии ғалло ва усули обкорӣ ниёз дорад. Бо дақиқият дар ҳисобҳо ва риояи асосҳои шиноии ғалло, деҳқон метавонад хароҷотҳояшро мувофиқсозӣ кунад ва самаранозияи баландтар дошта бошад. Мутобиқатии шиноии ғалло бо системаҳои навъи обкорӣ, аз ҷумла чормағзҳои ботинӣ (drip), ҳам аз ҷиҳати истифодаи манбаъҳо ва ҳам аз ҷиҳати рушди якхелаи гиёҳон хеле самаранок аст. Деҳқононе, ки ба ин асосҳо содиқанд, на танҳо ҳосили камро аз даст намедиҳанд, балки сифати баландтарро низ пешниҳод мекунанд.</p><p><strong>Мавоذي пайваста:</strong> Чормағзҳои ботинӣ ва фарқиятҳои онҳо, намудҳои чормағзҳои ботинӣ, <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d9%be%db%8c%d8%a7%d8%b2-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори бории пиёз дар ҳектар</a>, <a href="https://navar-abyari.ir/hosili-ju-dar-yek-gektar-omilhoi-tasirrason/">Омилҳои таъсиррасон ба ҳосили ҷав</a></p>\n<p><strong>Мавоذي пайваста:</strong> <a href="https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%DA%AF%D9%88%D8%AC%D9%87-%D9%81%D8%B1%D9%86%DA%AF%DB%8C/">D986D988D8A7D8B1 D8AADB8CD9BE DAAFD988D8ACD987 D981D8B1D986DAAFDB8C</a>, <a href="https://navar-abyari.ir/soybean-seed-per-hectare-iraq/">soybean seed per hectare iraq</a></p>','Қатъияти бозари бамия дар ҳектар: Рӯшноидеҳии умумӣ ва беҳтар кардан','Беҳтарин роҳҳо ва маслиҳатҳои амалӣ барои ҳисоб кардани миқдори тоҳук бамия ба ҳектар, бо дар назар доштан шароити иқлим ва усулҳои оварии тамчилӣ.','publish','closed','closed','bamia-seeding-rate-tajik',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
