INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи аҳамияти масофаи навиҳои рилсӣ дар кабудкунӣ</h2>\n<p>Кабуд як наботот аст, ки аз сабаби афзоиши зуд ва мӯҳлатҳои бӯроқ баъд баъд, идоракунии дақиқ манбаъҳои об яке аз масъалаҳои асосӣ дар деҳқонии он ҳисоб мешавад. Дар системаҳои обёркунии пошонакӣ ва навиҳои рилсӣ, муайян кардани масофаи мувофиқ байни навиҳо ва чидиши дуруст навиҳо, бевосита ба сифати наботот ва самаранокии иқтисодии замин таъсир мерасонад. Бисёри деҳқонон бо интихоби масофаҳои нодуруст, бо мушкилоте монанди заҳролании реша, афзоиши ғайритамғазиш ва задани об рӯбарӯ мешаванд. Дар ин роҳнамо, бо диққат ба стандартҳои техникӣ ва қоидаҳои амалӣ, ба баррасии <strong>Масофаи навиҳои рилсӣ кабуд</strong> мебароем, то роҳи дурустро барои кабудкунии оптималӣ равшан кунем.</p>\n\n\n\n<h2>Асосҳои техникӣ барои чидиши навиҳо (Row Layout) дар заминаёби кабуд</h2>\n<h3>Таъсири чуқурии решакуниш дар интихоби масофа</h3>\n<p>Решаҳои кабуд бештар дар 30 то 40 сантиметр дар болои сатҳи хок ҷамъ шудаанд. Бинобар ин, масофаи навиҳои рилсӣ бояд тавре танзим шавад, ки минтақаи тарки ҳосилшуда, минтақавари чуқурии решаҳои набототро пурра пӯшонад, бе он ки бо навиҳои дигар ғайрилозим баҳси ноларояд. Дар хокҳои сабук ва чоробар, масофаҳои калонтар метавонанд хатари шӯъури моддаҳои ғизоиро зиёд кунанд, аммо дар хокҳои сахт, масофаҳои кӯтоҳ метавонанд ба афзудиши об ва заҳролании реша оварда расонанд. Ин мувозинати дақиқ ба таҳлили дақиқи муҳити зист ва навъи хок ниёз дорад.</p>\n<h3>Стандартҳои андозаҳои масофаи навиҳои рилсӣ</h3>\n<ul>\n<li><strong>Фосила байни қаторҳо:</strong> Одатан барои навъҳои сабзи шӯрбои бо баргҳои пурвазӣ фосилаи 50 то 80 сантиметр тавсия дода мешавад. Ин фосила имкон медиҳад, ки ленти капиллярӣ дар маркази қатор ҷойгир шавад ва об дар атрофи асоси ғалладонаш бештар паҳн шавад.</li>\n<li><strong>Нои лентҳо:</strong> Истифодаи ленти капиллярӣ бо диаметри 8 то 15 миллиметр ва диаметри қатраҳо аз 15 то 20 миллиметр, бо сабаби ҳоҷати сабзи шӯрбои ба намуди ғолова ва ҳаракат кардан, арзанда аст.</li>\n<li><strong>Пӯшиши обрасиш:</strong> Суръати маъмули ралӣ (1/5 то 2/5 литр дар соат) кӯмак мекунад, ки минтақаи намнок васеътар шавад ва ҳоҷатии фосилаи калонтар байни лентҳо кам шавад.</li>\n</ul>\n<p>Барои фаҳмиши беҳтари тартиб, ба <a href="https://navar-abyari.ir/bean-strip-spacing-optimal-cultivation-standard/">манбаъҳои техникӣ дар бораи фосилаи лентҳо дар кишоварзии монанд</a> Таассурот ба ин ҷиҳат диҳед, зеро принсипҳои риёзии паҳши об дар сатҳҳои параллелӣ барои бисёр сабзавоти баргдор татбиқ мегардад.</p>\n\n<h2>Нақши навъи хок дар оптимизатсияи масофаи пайи чархбандии спинак (аспонҷ).</h2>\n<h3>Хокҳои гилӣ ва рӯғӣ: ду ҳикояи мухталиф</h3>\n<p>Дар хокҳои рӯғӣ ва сабук, зехкашии баланд боиси мунҳол шудани тез рутубат мегардад. Дар ин ҳолат, истифодаи масофаи байни сатҳҳое, ки калонтар аст (тақрибан 80 сантиметр) ва танзими пайи чархбандӣ барои обӣ кардани зуд-зуд бо камтарин дебит тавсия мешавад. Бинобар ин, хокҳои гилӣ ва вазнин зехкашии пурраш доранд; бинобар ин масофаҳои камтар (50 то 60 сантиметр) монеаи гирор шудани ризоҳои решаҳо ва рушди занбӯруҳо дар минтақаи реша мегардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-اسفناج-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت اسفناج: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop спинак</figcaption></figure>\n<h3>Таъсири шӯрӣ ва EC-и хок ба ҷамъофарин</h3>\n<p>Агар кӯҳу сӯсҳои спинаки шумо бо об ё хоке, ки шӯрияти нисбатии баланд доранд, рӯбарӯ бошанд, масофаи пайи чархбандӣ бояд чунин танзим шавад, ки имконияти шӯсташавии (Leaching) моддаҳои минералӣ вуҷуд дошта бошад. Ин маънои онро дорад, ки баъзан бояд як пайи иловагиро дар ҳар як сатҳ ё масофае зиёда аз одадии стандардро илова кард, то ки зонаи шусташуда бо оби обӣ бо пайи ҳамсоя даргир нашавад ва даргирии кимиёвии об дар реша коҳиш ёбад.</p>\n\n\n\n<h2>Нуқтаҳои амалӣ барои фоидаоварии максималӣ аз обӣ кардани пайи чархбандӣ</h2>\n<h3>Барқароркунии дуруст ва ҳамсатҳкунии лентҳо</h3>\n<p>Яке аз бузургтарин хатоҳо дар муайян кардани масораи лентаи тири菠菜 (спинак), ҷойгиркунии нодурусти лента дар ҳолати ҳақиқӣ аст. Лентаҳо бояд дақиқан дар хатти саф ва ҳамсатҳ бо сатҳи хок ё ним сантиметр поёнтар қарор дошта бошанд. Агар масораи лента то рӯяк кам бошад (масалан, камтар аз 5 сантиметр), намӣ мустақиман бо асоси сабзавотҳо дар тамос мебошад ва хатари бемориҳои қарафунгиро дукарата мекунад. Агар он зиёд бошад, об дар маркази саф ҷамъ мешавад ва решаҳои канорӣ хушк мемонанд.</p>\n<h3>Техники обёрӣи паулсӣ ва идоракунии намакинӣ</h3>\n<ol>\n<li><strong>Вақтгузории обёрӣ:</strong> Спинак дар шартҳои ҳавои гарм обёрӣи паулсӣ (чанд дозаи хурдро дар як рӯз)-ро ба як дозаи калон тақдил мекунад. Ин усул имкон медиҳад, ки лентаи тир дар масораҳои стандартӣ намии равшанро дар давоми решаҳо нигоҳ дорад.</li>\n<li><strong>Низорӣ бар EC-и хуруҷ:</strong> Бо роҳи низокунии оби хориҷшуда аз зехкунандаҳои майдони кишт, шумо метавонед масораи лентаро навсозӣ кунед. Агар EC-и хуруҷ баланд бошад, ин нишондиҳандаи зарурати зиёд кардани шустушӯ ва, бо ин замина, бозбаррасии ҷойгиркунии лентҳост.</li>\n<li><strong>Изолятсиякунонӣ:</strong> Истифода аз обшедоши (оқимандагӣ) дар қадди каналҳои асосӣ, аз норасидани об дар минтақаҳо бо фосилаҳои камтар пешгирӣ менамояд ва ба лентаи чӯп (drip) имкон медиҳад, ки бо фишори мувофиқ кор кунад.</li>\n</ol>\n<p>Агар аз системаҳои зерзаминавӣ истифода баред, принсипҳои ҷойгиршавӣ дигаргун хоҳад буд; аммо барои лентаи чӯп (drip tape), риоя кардани фосилаҳои стандартии сатҳӣ муҳим аст. Шумо метавонед маълумоти бештарро дар бораи <a href="https://navar-abyari.ir/%d9%87%d9%85%d9%87-%da%86%db%8c%d8%b2-%d8%af%d8%b1%d8%a8%d8%a7%d8%b1%d9%87-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%b2%db%8c%d8%b1%d8%b3%d8%b7%d8%ad%db%8c/">оборивии зерзаминавӣ</a> баррасед, то фарқияти ин ду системаро беҳтар фаҳмед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-اسفناج-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت اسفناج: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop спанач</figcaption></figure>\n\n<h2>Таъсири фосилаи лентаи чӯп (drip) ба самаранокии ва сифати спанач</h2>\n<p>Байни ҷойгиршавии лентаи чӯп (drip) ва сифати ниҳоии маҳсулот робитаи мустақим вуҷуд дорад. Вақте ки фосилаи лентаи чӯп барои спанач ба таври дуруст ҳисоб карда шавад, тарозии якхелаи гӯҳовии (пӯлодпакании) растаниҳо боиси он мегардад, ки дар вақти ҷамъоварӣ, андозаҳои баргҳо ва вазни растаниҳо якхела бошанд. Гардиши андоза дар як қатор бевосита ба арзиши тиҷоратии маҳсулот таъсир мерасонад. Ғайр аз ин, нигоҳ доштани намки мувофиқ дар минтақаи рӯидагиҳои (ростаниҳо) стресси муҳити растаниҳоро кам мекунад ва ба кам шудани истифодаи моддаҳои партовии (азудҳо) кимиёвӣ оварда мерасонад, зеро моддаҳои таровӣ осон тавассути ҷараёни об дар лентаи чӯп ба рӯидагиҳо мерасанд.</p>\n\n\n\n<h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2>\n<h3>Фосилаи оптималии тасмаи чуқорики бо қатъқумуспинак дар шароити куронӣ чӣ қадар аст?</h3>\n<p>Дар шароити куронӣ беҳтар аст, ки фосилаи тасмаи чуқорикиро кам намуда аз тасмаҳое, ки ракиши об камтар ва шумораи чуқуркӯбеш бештаранд истифода барад, то минтакаи намнок чуқуртар шавад ва хсарбории об бо баомобии сатҳӣ пешгирӣ гардад. Ин кор боиси шадакунӣи бунбӯри дараҳташ чуқуртар мегардад.</p>\n<h3>Оё имконоти истифодаи тасма дар сатҳҳои хамгун вуҷуд дорад?</h3>\n<p>Бале, дар деҳқониҳои андозаи хеле калон, ҷойгиркунии хамгун (Cross-tape) баъзан истифода мешавад, то таъмин намудани обӣ ба қисмҳои сарҳади сатҳҳо дақиқ шуда бошад. Ин усул ба ҳисобкирии дақиқи фишор ниёз дорад, то ки тасмаи асосӣ ва хамгун дар як вақт кор накарда ва ба фишори таъсир нарасонанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-اسفناج-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت اسفناج: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>фосилаи тасмаи чуқурики ҷойгиркунии сатҳҳои қатъқуми спинак</figcaption></figure>\n<h3>Таъсири фосилаи тасмаи чуқурикӣ ба ӯсмони оғозӣ чӣ гуна аст?</h3>\n<p>Бо зиёд шудани фосилаи тасмаи чуқурикӣ, ӯсмони оғозӣ дар фазои байни сатҳҳо зудтар меафрӯзад. Дар натиҷа, бояд фосилаи меъёниро чунин интихоб кунед, ки дар тарафи обдорӣ, фазои кофӣ барои кушодани хок ё истифодаи ӯсмонкушиҳоро дар байни сатҳҳо вуҷуд дошта бошад, бе он ки ба тасмаи чуқурикӣ халал нарасад.</p>\n\n<h2>Хулоса ва тавсияҳои ниҳоӣ</h2>\n<p>Ҷиҳатбандӣ <strong>Фосилаи нақли тиббӣ барои каду-бодиринг</strong> Яке раванди динамикӣ аст, ки ба назорати мунтазам ниёз дорад. Бо дар назд гирифтани намуди хок, шӯри об ва шартҳои иклимӣ, шумо метавонед ҷойгиршавиро барои ҳар фаввора мукаммал намоед. Истифодаи технологияҳои дақиқ барои оғоз, на танҳо хароҷотҳои энергия ва обро кам мекунад, балки бо таъмини сифати якхела, имконияти фурӯши беҳтари маҳсулотро дар бозор зиёд мекунад. Кишоварон метавонанд аз манбаъҳои муарраб монанди <a href="https://navar-abyari.ir/mikyori-hosili-marza-dar-yek-gektar-rahnamoi-purra/">раҳнамои ҳисоб кардани миқдори маҳсулот дар ҳектар</a> ва идоракунии беҳтарсозии кишт истифода баранд, то тамоми занҷираи кишт аз тоҳук то ҷамъовариро пурраи идора кунанд. Дар ниҳоят, иҷрои дурусти нақли тиббӣ ва риояи принсипҳои риёзии ҷойгиршавӣ, калиди муваффақият дар истеҳсоли сабзавоти сифатнок ва самаранокист.</p>\n<p><strong>Маводи муталлиқ:</strong> <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%da%a9%d8%b1%d9%81%d8%b3/">Нақли тиббӣ барои камч: Раҳнамои умумии оғоз, фосилаҳо ва нуқтаҳои калидӣ</a></p>','Фосилаи банди пухт дар ҳосилнокии шубора: Стандартҳои тавсияшуда','Интихоби масофаи мувофиқи бастаи чангроп дар парҳези аспара нақши калидӣ дар идоракунии манбаъҳои об ва нигоҳдории намии реша дорад. Ин мақола ба баррасии меъёрҳои масофа, тартиби сафҳо ва нуқтаҳои амалӣ барои самаранокӣи баландтарин ишора мекунад.','publish','closed','closed','fosoil-bandi-pukht-dar-hosilnoikii-shubora-standardhoi-tavsiashuda',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
