INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على نصائح تقنية لزيادة إنتاجية القطن لكل هكتار باستخدام نظام الري بالتنقيط (نظام كابل). دليل مفصل للمزارعين لتحسين المحاصيل وخفض تكاليف المياه عبر إدارة الري الفعّالة.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
