INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада ороиши зарф (neta) ва зӣра</h2>\n<p>Зӣра (Anethum graveolens) яке аз рахнаҳои бӯйнок ва доруӣ аст, ки бо сабаби бӯи хушбӯ, таъми беназир ва хусусиятҳои бисёр давоӣ дар бозорҳои дохилӣ ва экспортӣ ҷойгоҳи махсус дорад. истеҳсокиони зӣра ҳамеша ба мушкилоти асосии идоракунии беҳтарин манбаъҳои об дучор мешаванд; зеро бисёр минтақаҳои кишт ин рахна нокилии об ва зерошҳои хушкшавиро мекашанд. Усулҳои ороиши анъанавӣ (масалан, тағозуб) на танҳо ба неъомати зиёд оби мерезанд, балки метавонанд боиси тағозуби решаҳо, зиёдшудани бемориҳои қаричи ва дар натиҷа камшави ҳосилнокӣ гарданд. Аз ин рӯ, системаи зарф, ки як шакли пешрафта аз ороиши боқатонавӣ ба ҳисоб меравад, ҳамчун ҳалли самаранок ва ҳоким барои зиёд кардани <strong>миқдори ҳосили зӣра дар ҳектар бо зарф</strong> тақдим гардидааст. Ин система бо ҷорикунӣи мустақими об ва моддаҳои ғизоӣ ба минтақаи решаҳои рахна, боиси камшавии буғшавӣ, пешгирии ҷамъшавии намкҳо дар сатҳи хок ва дар натиҷа идоракунии беҳтар наъъубҳо мешавад. Дар асос, ба таҳлили муфассалтар олаҳоти техники, иқтисодӣ ва амалӣ ин мавзӯъ мегардем, то тасвири пурра аз имкониятҳои ин технология пешкаш шавад.</p>\n\n<h2>омилҳои муассир барои зиёд кардани миқдори ҳосили зӣра дар ҳектар</h2>\n<p>Барои расидан ба мақдори максималии ҳосил дар ҳектар, дониши мутавалли ва ҳаракати мувофиқ иловораҳо лозим аст. Зӣра рахнаест, ки ба намди миёна, рӯшнии кофӣ ва ҳарорати мувофиқ ниёз дорад, аммо ба тағозуби баланди ҳиссо мекунад. Зарф бо сохтани зарфи намди идорашуда ва ихтиёрӣ, мувозинати мувофиқро дар решаҳо эҷод мекунад, ки барои афзоиши беҳтарин зӣра мукаммал аст.</p>\n<h3>1. Фасоли ботилҳо ва чукунии каланд</h3>\n<p>Фавқуҳудуди мувофиқи парсаи заҳм вобаста ба минтақа, шароити иқлимӣ ва намуди хок тағйир меёбад. Одатан, фосила байни парсаҳо тақрибан 100 то 120 сантиметр ва фосилаи буттаҳо дар дохили парса байни 5 то 10 сантиметр тавсия дода мешавад. Дар системаи нурбӣ-чашник, нурҳо бояд дақиқан дар зери парсаҳо ва бо амикии 5 то 7 сантиметр ҷойгир шаванд, то ки об бевосита ба ҳалқаи решаҳо расад, на он ки дар сатҳ монанд. Ин ҷамъшавии дақиък самаранокии истифодаи обро босуръат боло мебардорад.</p>\n\n<h3>2. Интихоби бӯи бехосор ва зичии парҳезкунӣ</h3>\n<p>Истифодаи бӯи солим, тоза ва зич нақши муайянкунандаро дар натиҷаи ниҳоии меҳварт дорад. Таҳқиқ <a href="https://navar-abyari.ir/dill-seed-per-hectare-factors-increase-yield/" target="_blank" rel="noopener">Омилҳои зиёдкунандаи зичии бӯи заҳм дар гектар</a> Нишон медиҳад, ки зичии парҳезкунии муоддатан тақрибан 15 то 20 килограмм дар гектар аст. Ин миқдор ҳатман бояд бо шароити сохтори хок ва системаи обёрӣ интихобшуда мувофиқат кунад. Агар фосилаи парсаҳо аз ҳадди муоддатан камтар бошад, рақобат барои об ва моддаҳои ғизоӣ зиёд шуда, ҳаракати решаҳо ниҳода мешавад. Бинобар ин, танзими дақиқи шумораи буттаҳо дар воҳиди сатҳ бевосита ба истеҳсоли ниҳоӣ таъсир мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-ارزن-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت ارزن در هکتار با نوار تیپ - تصویر 1"/><figcaption>crop yield per hectare drip irrigation арзон</figcaption></figure>\n\n<h2>Нуқтаҳои амалии иҷрои системаи нурбӣ-чашник барои заҳм</h2>\n<p>Иҷрои дурусти системаи нурбӣ-чашник лозимити диққатро дар насб, танзими техникӣ ва нигоҳдории доимиро талаб мекунад. Дар ин қисм, нуқтаҳои асосии амаликуноро меомӯзем, то таъмини коркарди комил ва беҳтарини система ва пешгирии мушкилоти имконпазир исбот шавад.</p>\n<h3>Дусти номураб ва филтрасия</h3>\n<p>Яке аз мушкилоти маъмул дар тизимҳои обёрӣ дар инқотӣ ғуфтишавии филтрҳо ва ғиштҳо ба сабаби рағамонанди намакҳо ё зарраҳои мутолим аст. Гизимеъ дар марҳилаҳои аввали рушд ниёз ба ҳифз ва рушди тез дорад, бинобар ин як тизими филтрасияи бениҳоят мувофиқ (афзал филтри дарозинишдор бо тор 120 то 170 ё филтрҳои сиклони) бояд дар ибтиди асосии хат насб шавад. Инчунин, интихоби намуди ғиштҳо (якпайваста ё чандпайваста) вобаста ба масофаи байни бахшҳо ҳайатӣ аст. Ғиштҳо ба сабаби камтар арзиши, осонтар насб шудан ва коминг ба зарурати гардиши хат, барои бағалҳои миёна ва саноатӣ гӯяндаи маъмулӣ мебошад. Истифодаи ғиштҳои шаффоф имконияти мушоҳидаи паҳншавии баробари обро фароҳам меорад.</p>\n<h3>Барноманавии обёрӣ ва тасмиеъи майҳалӣ</h3>\n<p>Ғиштҳо имконияти анҷоми ҳамзамони обёрӣ дар инқотӣ ва тасмиеъи майҳалӣ (Fertigation) -ро фароҳам меоранд. Гизимеъ дар марҳилаҳои ҳасос монанди пайдо шудани гул, ташкили мева ва расидани мева ба об ниёзи шиддат дорад. Беҳтар аст, ки барномаро дар асоси ниёзи бағалӣ, ҳаросати ҳаво ва рутубати хок дақиқ танзим шаванд. Миёнаи масарофи об барои гизимеъ бо ғиштҳо тақрибан 60 то 80 фоиз камтар аз обёрии анъанаии хокӣ аст. Барои беҳтар даъриф баррасӣ, омӯзиши фарқи ғиштҳо аз обёрӣ дар инқотӣ тавсия дода мешавад. Ғиштҳо танҳо минтақаи решаи бағалро намобанд, инчунин ин аз рушди алафҳои ҳарз дар байни бахшҳо пешгирӣ мекунад ва хароҷоти муборизаи шимиявиро кам мекунад.</p>\n\n\n<h3>Дидгорӣ ба сифати об ва хок</h3>\n<p>Кифяти об барои системаи ришта-тобӣ аҳамияти калон дорад. Обе, ки сахтии баланд ё намакҳои ҳалшудаи зиёд дорад, метавонад сабаби дагӣ дохилкунандагон ё риштаҳо гардад. Тавсия мешавад, ки таҳлили об ва хӯрок ба таври давомнок иҷро карда шавад. Инчунин, истифодаи моддаҳои кислотагинкунанда барои танзими pH-и об ва пешгирии ҷамъшавӣ дар баъзе минтақаҳо зарур аст. Ҳаракат дар рӯйҳои решаҳо ва пешгирии зарари физикӣ ҳангоми намдан ба кори беҳтари система мусоидат мекунад. Дар ин самт, шиносӣ бо миқдори сарфадиҳии садҳакта барои ҳисобҳои иқтисодии ниҳоӣ муфид хоҳад буд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-ارزن-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت ارزن در هکتار با نوار تیپ - تصویر 2"/><figcaption>crop yield per hectare drip irrigation арз</figcaption></figure>\n\n<h2>Ҷавоб ба саволҳои мушоҳидашуда (FAQ)</h2>\n<h3>Оё системаи ришта-тобӣ барои арз арзон аст?</h3>\n<p>Бале, ба қайддиҳии коҳиши қатъии ҳарҷаи об, қувваи меҳнатӣ ва сарфи кимиёвӣ, бозгашти сармояи системаи ришта-тобӣ одатан дар фасли дуюм ё сеюми ҷамъи ҳосил ба даст оварда мешавад. Инчунин, афзоиши ҳаҷми истеҳсол дар садҳакта ба самаранокии иқтисодии умумии деҳқонӣ мусоидат мекунад ва муфиднокии молиявии ин технологияро равшан месозад.</p>\n<h3>Фосилаи ришта-тобӣ аз ҷои гулгумӣ чӣ қадар бояд бошад?</h3>\n<p>Риштаи тобӣ бояд бо фосилаи 10 то 15 сантиметр аз хати гулгумӣ ва дар чуқурии тақрибан 5 то 7 сантиметр дар хӯрок ҷойгир карда шавад. Ин фосила имкон медиҳад, ки решаҳо ба об расид, бе он ки бевосита дар зери фишори паҳншавӣ қарор гирад ва аз рӯишҳои нобарқарор барги пешгирӣ карда шавад.</p>\n<h3>Оё метавон ришта-тобиро барои дигар набототи ароматистӣ истифода бард?</h3>\n<p>Бале, системаи каши (drip) бисёр хеле анеластик аст. Касбиҳои зиёд бо ҳолои кишт монанд, чун митъа, шорбат ё митъаи дигар, низ аз фаваиди ин система истифода мебаранд. Барои ҳосилнокӣ, шумо метавонед дар бораи кашӣ барои кабудгирҳо маёрнаме кунед, зеро ониҳо асосҳои техникии хеле монанд доранд.</p>\n\n\n<h2>Хулоса</h2>\n<p>Истифодаи системаи кашӣ барои кишт арзан, роҳи хеле хеле хеле барои деҳқонони муосир аст, ки дар поёни фароварӣ, сифати маҳсулот ва кам кардани хароҷоти амалияёт меёбанд. Бо риояи асосҳои зичии кишт, насби дурусти кашӣ ва нақшаи дақиқ обӣ, метавон интизор дошт, ки <strong>Дараҷаи партоби арзан дар гектар бо кашӣ</strong> ба ҳудуди хеле баланд расад. Сармоягузорӣ дар ин технология на танҳо ба истеҳсоли маҳсулоте бо сифати баланд ва лазизи хеле хеле оварда, балки нақши муҳимро дар ҳимоя аз манбаҳои об ва устувории муҳити зист боз мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-ارزن-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت ارزن در هکتار با نوار تیپ - تصویر 3"/><figcaption>crop yield per hectare drip irrigation арзан</figcaption></figure>\n<p>Пешниҳод мешавад, ки деҳқонҳо пеш аз амалӣ кардани система, бо мутахассисони маҳаллӣ машварат кунанд ва шароитҳои маҳаллии боғро дар назар гиранд. Пайваст кардани дониши техникии ҳозиразамон бо таҷрибаи маҳаллӣ ва ошёрӣ ба мушкилоти заминагии боғ, калиди ҳосилнокӣ дар кшт арзан бо кашӣ аст. Боғҳое, ки аз ин усул истифода мебаранд, одатан қобилияти баландтари муқобимати ба таҳавулотҳои обӣ ва илмоӣ зоҳир мекунанд ва маҳсулоти ҳамвортар истеҳсол мекунанд.</p>\n<p><strong>Маводи пайвастгӣ:</strong> Оборӣ чист ва фоидаҳои он чист? <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A8%D8%A7%D9%82%D9%84%D8%A7-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миқдори тохук дар ҳектар</a>, фарқияти нутқакӣ бо системаи ободории қатравӣ</p>\n<p><strong>Мавзӯъҳои пайваста:</strong> <a href="https://navar-abyari.ir/%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D8%AE%D8%B1%D8%B3%D8%A7%D8%A8%DB%8C-%DA%86%DB%8C%D8%B3%D8%AA-%D9%88%DB%8C%DA%98%DA%AF%DB%8C-%D9%87%D8%A7-%D9%88-%D9%85%D8%B9%D8%A7%DB%8C%D8%A8/">D8A2D8A8DB8CD8A7D8B1DB8C D8AED8B1D8B3D8A7D8A8DB8C DA86DB8CD8B3D8AA D988DB8CDA98DAAFDB8C D987D8A7 D988 D985D8B9D8A7DB8CD8A8</a>, <a href="https://navar-abyari.ir/%D8%AA%D9%81%D8%A7%D9%88%D8%AA-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A8%D8%BA%D9%84-%D8%AF%D9%88%D8%AE%D8%AA-%D9%88-%D9%BE%D9%84%D8%A7%DA%A9%D8%AF%D8%A7%D8%B1/">D8AAD981D8A7D988D8AA D986D988D8A7D8B1 D8AADB8CD9BE D8A8D8BAD984 D8AFD988D8AED8AA D988 D9BED984D8A7DAA9D8AFD8A7D8B1</a></p>','Самеъи зироати арзан дар як гектар бо системаи капель: Мукаммал дастурӣ барои зиёд кардан самаранокии','Система чек (напёр) яке аз роҳҳои навомӯзи обкоркунии ҳунарӣ буда, қобилияти баланди зиёд кардани ҳосилнокии ҷӯ дар ҳектар дорад. Ин мақола омӯзиши омили таъсиррасон ба самаранокии ҷӯ бо чек, нуқтаҳои амалии кишварнокунӣ ва обкунӣ ва ҷавоб ба саволҳои маъмулро меомӯзад, то ки деҳқонon беҳтарин истифодабарӣ дошта бошанд.','publish','closed','closed','samari-arzani-kaapeli-dasti',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
