INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Learn how to manage pea pests and diseases using drip irrigation. This comprehensive AFP guide provides technical strategies for farmers and irrigation professionals.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','Pea Pest and Disease Management with Drip Irrigation: Comprehensive Guide' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Пайванди пинҳона байни оборӣ ва соҳимиат барои нохӯд</h2><p>Кишлодориёне, ки бо кишт ва парвариши нохӯд машғуланд, аксар вақт бачавии асосии худро дар бораи кам шудани истеҳсоли ҳосил аз сабаби зараррасонҳо ва бемориҳои қаларзӣ ифода мекунанд. Ҳамаинҳол, бисёр мушкилоти нисбат ба парвариш ва ҳифзат ба идоракунии номуносиби манбаъҳои муҳити зист пайваст буда, бештар дар ҳисоби оборӣ мебошад. Нохӯд решаи ноғарии обориро барои ғизои бешубораи обӣ дорад ва даромадан дар ноқилии ошуборҳо ва хунукӣ метавонад муҳити хушбахт барои пайдоиши бемориҳои биохимиявиро ба вуҷуд орад. <strong>Обории нақрагӣ</strong> Ва чорчӯбаи тип бо тағйир додани динамикии намӣ нақшаро тағйир медиҳад. Ин усулҳо ба ҷои хунукшавии тамоми замини боғро, обро мустақиман ба қисми решаҳо мересонанд, аммо агар принсипҳои онҳо дуруст иҷро нашавад, метавонад бачавии нав пайдо шавад. Дар ин мақола, ба асоси принсипҳои илмӣ ва таҷрибаи амалӣ, роҳҳои истифодаи системаҳои обории дақиқ барои идоракунии зараррасонҳо ва бемориҳои нохӯдро баррасӣ мекунем.</p><h2>Таъсири бевоситаи намӣ барои паҳншавии бемориҳои қаларзӣ</h2><p>Беморӣҳое чун зангӣ (Rust), байоспора ва боича ба таври мустақим бо намии нисбӣ алоқаманданд. Дар системаҳои обории хирорӣ ё баронӣ, қатраҳои об сӯрӣҳоро шуста ва хокистарашро дар тамоми сатҳи замин паҳн мекунанд. Аммо дар обории қатрагӣ мушкилоти дигар аст. Агар қатраҳо бо фишори баланд ба баргҳо парса шаванд ё агар масофаи наздикии лентаи обдор бо асоси растанӣ хеле кам бошад, намӣ бевосита ба қисми баробаррасонанда таъсир мерасонад. Барои идоракунии ин масъала бояд аз тарҳи дурусти система истифода барем. Истифодаи қатрагарҳое, ки суръати рафтанашон мувофиқ аст, ва пешгирии хирам шудани мустақими баргҳо аз нуктаҳои муҳим аст. Дар умум, нигоҳ доштани гардиши реша бе хирам шудани зиёди тоҷи растанӣ, калиди муваффақият аст. [a href="https://navar-abyari.ir/important-tips-drip-tape-irrigation/" target="_blank"]Нуктаҳои муҳим дар обории лентаии наздик[/a] метавонад роҳнамои хуб барои танозукунии ин мувозинат бошад.</p><h2>Идоракунии зараррасонҳои бозмои замин ва нематодаҳо тавассути обори дақиқ</h2><p>Зараррасонҳои бозмои замин, аз ҷумла ширеҳо ва никудаир, дар муҳити нарм ва ғарғарӣ фаъолияти бештар доранд. Обории қатрагӣ бо кам кардани намии сатҳии замон боми, метавонад рафтори муҳаррики зараррасонҳоро тағйир диҳад. Инчунин, бисёре аз қарчҳои замини монанди фосариум дар шароити хирами об ба қудрати максималии худ мерасанд. Дар заминҳои обории қатрагӣ имконияти обори мутаваққиф ва хушккунии назоратшаванда вуҷуд дорад. Усуле, ки ба сифати «обориҳои даврагӣ» шинохта мешавад, ба растанӣ имкон медиҳад, ки шиддати ноҳамҳоро таҷриба кунад, ки муқовиматашро дар муқобили патогенҳои замини меафзояд. Бо вуҷуди ин, набоист аз хатари сироят тавассути системаи обори фаромӯш кард. Агар обест, ки истифода мешавад, ба нематода сироятёфта бошад, қатрагарҳо метавонанд ин зараррасонро бевосита ба минтақаи реша расонанд. Бинобар ин, филтратсияи мувофиқи оби воридотӣ аз афкори асосӣ аст.</p><p></p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-نخود-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های نخود با آبیاری قطره‌ای - تصویر 1"/><figcaption>аштубориҳои булӯравӣ, бемориҳо, ороронии чашонакӣ, нуҳут</figcaption></figure><h2>Нақши лавҳаи ороронӣ дар коҳиши бемориҳои байоспора ва плумпоксӣ</h2><p>Лавҳаи ороронӣ бо сабаби арзон будан ва осон насб шудан, беҳтарин имконият баро бағонаҳои нуҳут аст. Аммо лавҳаи ороронӣ табииан як системаи чашонакӣ мебошад ва ҳамон мушкилоти намдорӣ дорад. Дар нуҳут, фосилаи лавҳа аз сатҳи партовидан бояд таврӣ танзим шавад, ки решаҳо дар минтақаи хунук бошанд, варакҳо хушк монанд. Истифодаи лавҳаҳо бо даби пасттар ва хатҳои дуртар меътонад ба паҳншавии беҳтари намдортарин кӯмак кунад. Инчунин, шустани муносиби система пас аз анҷоми мавсими партовидан барои пешгирии ҷамъомадиси қулайҳои хашардоркуш ва бемори дар рагҳои лавҳа зарур аст. Инfectionи дохили лавҳа метавонад манбаи асосии патогенҳо дар соли оянда бошад. Барои тарҳи дурусти шабака, таҳқиқ [a href="https://navar-abyari.ir/comprehensive-irrigation-tape-greenhouse-guide-0-to-100/" target="_blank"]раҳнамоии ҷамъи ороронии лавҳа[/a] тавсия мебошад, гарчанде ки принсипҳои он барои ҳашокиро ошён низ кор мекунад.</p><h2>Нуқтаҳои амалӣ барои деҳқонҳо: нақшаи идоракунии хашардорҳо бо ороронии чашонакӣ</h2><p>Барои он ки аз фоидаҳои ороронии чашонакӣ дар коҳиши зарари гиёҳҳо истифода баред, риояи нуқтаҳои поён зарур аст. Ҳар яке аз инҳо ба таври мустақим ба саломатии гиёҳ ва коҳиши ниёз ба заҳари кимиёвӣ таъсир мерасонад:</p><ul><li><strong>Аз оронониш дар бозпайи шаб оғоз наварзинед:</strong> Оронониш дар сатҳҳои охирини рӯз боиси ин шудан мекунанд, ки намдор то субҳ дар молик боқӣ мемонад. Ин ҳолат барои занбар ва гурғурҳо мувофиқ аст. Оронониши субҳӣ беҳтарин ҳангоми барҷои обӣ мебошад.</li><li><strong>Истифодаи чашонакҳои шотронгиашоӣ:</strong> Дар марҳилаҳои ҳассоси афзоиши нӯх, паҳнкунии якхелаи об метавонад боиси беҳаромии рутубат гардад. Чархзанбҳои шатранҷӣ имконияти идоракунии рутубати навбатӣро фароҳам меоранд.</li><li><strong>Танзими шудури хатҳо:</strong> Шудури номувофиқи навози ғундорӣ (тип) метавонад боиси хушкшавии анҷоми хат ва обӣ будани ибтидои хат гардад. Ин ноустуворӣ боис мешавад, ки як қисми майдон ба хароба осебпазир шавад ва қисми дигар устувор боқӣ монд. [a href="https://navar-abyari.ir/tips-before-buying-drip-tape-irrigation-iq/" target="_blank"]Тавсияҳое пеш аз хариди навози ғундорӣ[/a]-ро барои интихоби намунае, ки ба замини шумо мувофиқ аст, мавҷӯъ кунед.</li><li><strong>Назорати дақиқ: боронвабарӣ ва обёрӣ:</strong> Системаҳои обёрии зеҳнок ё ҳатто сенсорҳои рутубати хок ба шумо кӯмак мекунанд, ки аз обёрии ғайридоимӣ, ки сабаби асосии паҳншавии бемористӣ аст, худдорӣ кунед.</li></ul><h2>Таъсири кишт омехта ба идоракунии хароба бо обёрӣ</h2><p>Аммо маудоди асосии мо обёрӣи нӯх аст, вале бисёр деҳқонҳо кишт омехтаро иҷро мекунанд. Идоракунии обёрӣ дар кишт омехта мушкилтар аст, зеро ниёз ба оби ҳар як растани гуногун аст. Агар нӯх-ро бо ҷӯр ё ҷӯр омехта кишт карда бошед, рутубати зиёдатар аз ҳад барои ҷӯр метавонад ба бемориҳои нӯх оварда расонад. Дар ин ҳолат, истифодаи чархзанбҳои алоҳида ё танзими дақиқи сарфи ҳар хат муҳим аст. Инчунин, дар минтақаҳои гарм, кишт омехта метавонад бо сабаби гуногунии муҳити зист харобаҳои ҳашаротро ҷалб кунад, бинобар ин идоракунии рутубат тавассути обёрии дақиқ танҳо роҳ барои нигоҳ доштани мувозинат мебошад. [a href="https://navar-abyari.ir/mixed-crop-yield-per-hectare-iraq/" target="_blank"]Масраҳи кишт омехта дар гектар[/a] метавонад дар сурате беҳтарин бошад, агар обёрӣ низ беҳтарин бошад.</p><h2>Саволҳои оддӣ (FAQ) дар бораи харобаҳои нӯх ва обёрии қатрагӣ</h2><h3>Оё орошӣ-капусӣ (қабулӣ) боиси зиёд шудани кукруккаҳо дар ноҳут мешавад?</h3><p>Не, шартом он аст, ки намнокии мувофиқ нигоҳ дошта шавад. Кукруккаҳо дар набототи дорои стресси обӣ бештар ҷамъ мешаванд. Орошӣ-қабулӣи мунтазам ва дақиқ бадҳозии решаҳоро кам карда, аз ҷамъшавии кукруккаҳо пешгирӣ мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-نخود-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های نخود با آبیاری قطره‌ای - تصویر 2"/><figcaption>азоёни ҳашари зараррасон, бемориҳо, орошӣ-қабулӣ, ноҳут</figcaption></figure><h3>Кай бояд системаи ороширо тоза кард ё шуст?}</h3><p>Пасохи тамом шудани ҳар фавсони кишт ва пешинаи фавсони оянда, бояд ҳатман системаро бо маҳлуҳи зараррасонкунанда ё кислотагӣ тоза кард, то аз рӯшани биофильми дар дохили нӯлҳо, ки метавонад сарчашмаи ҳашари зараррасон бошад, пешгирӣ карда шавад.</p><h3>Оё нӯлҳои орошӣ-қабулӣ барои заминҳои ганҷӣ мувофиқанд?</h3><p>Дар заминҳои ганҷӣ, нафакуниш паст аст ва об дар минтақаи назди қубурҳо ҷамъ мешавад, ки метавонад боиси бемориҳои реша шавад. Дар ин заминҳо, беҳтар аст аз қубурҳои дорои шиддати баландтар ва фосилаи бештар истифода кунед, то об фурсат дошта бошад, ки чуқуртар ҷойгир шавад.</p><p></p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-نخود-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های نخود با آبیاری قطره‌ای - تصویر 3"/><figcaption>азоёни ҳашари зараррасон, бемориҳо, орошӣ-қабулӣ, ноҳут</figcaption></figure><h2>Хулоса: Сармоягузорӣ ба як парҳези доимоистоя</h2><p>Идоракунии зараррасонандагон ва бемориҳои нахӯд бо обкунии тамға-тамогонӣ, тағйири андеша аз «обкунӣ барои афзоиш» ба «обкунӣ барои идоракунии муҳит»-ро талаб мекунад. Бо хориҷ кардани намии зиёдат аз таҷи растани ва хокҳои сатҳӣ, шумо қабати муҳофизатарии қавӣ вазъ ба занбӯруҳо ва зараррасонандагони хокӣ эҷод мекунед. Гарчанде ки ин усул дар асбобнокӣ, нақшабарорӣ ва нигоҳдории он андешамандиро талаб мекунад, боздоишаш дар кам кардани аз даст рафти ҳосил ва расонаҳои зарбзароки, назаррас мешавад. Ба деҳқонон тавсия дода мешавад, ки пеш аз сармоягузорӣ дар системаҳои обкунакӣ, ба сифати об ва намуди хоки худ низ диққат диҳанд. Барои фаҳмиши беҳтари миқдори бодадҳои лозима дар паҳлу системаҳои обкунии дақиқ, метавонед аз [a href="https://navar-abyari.ir/miqdori-tukhmi-zira-siyoh-dar-gektar-dasturi-kisht/" target="_blank"]раҳнамои миқдори бодади нахӯд дар гектар[/a] истифода баред, то ки замини худро ҳамчун як системаи якпорча нақшабарорӣ намоед.</p><p></p>\n<p><strong>Мундариҷаҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/mikdori-tukhmi-zira-siyoh-dar-gektar-dasturi-kisht/">mikdori tukhmi zira siyoh dar gektar dasturi kisht</a>, <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%A7%D8%B1%D8%B2%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D8A7D8B1D8B2D986 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/comprehensive-irrigation-tape-greenhouse-guide-0-to-100/">comprehensive irrigation tape greenhouse guide 0 to 100</a>, <a href="https://navar-abyari.ir/important-tips-drip-tape-irrigation/">important tips drip tape irrigation</a></p>','Машқоти муҳофизати наъфаз ва беморҳои нхӯд аз зараррасонандагон бо обёркунии бозораки: Раҳнамои комил','Орори коҳазӣ танҳо як усули интиқоли об нест, балки барои идоракунии намӣ ва дурнамои зараранҷӯҳҳо хизмат мекунад. Дар ин мақола, мо таҳлил мекунем, ки чӣ гуна танзими дурусти системаи орори коҳазӣ паҳншавии бемориҳои занбадорӣ ва зараранҷӯҳҳои хокӣ-зоъро дар нахӯдро кам мекунад.','publish','closed','closed','muhofizati-naftaz-bemori-ho-ho-ho-nakhud-dri-droshandib',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
