INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','اكتشف استراتيجيات فعّالة للتحكم في الآفات والأمراض الفطرية والبكتيرية في محصول البصل الأخضر عند استخدام نظام الري بالتنقيط. دليل تقني دقيق للمزارعين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
