INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада: Аҳамияти идоракунии намнокӣ дар парвариши шпинатӣ (пиёзонҳо)</h2>\n<p>Пиёзонҳо (шпинатӣ) растаниест, ки ба сабаби рушди тез ва ҳассосияти баланди решаҳо ба намнокии зиёд, ба бемориҳои занбӯрӣ ва бактериявӣ мубтало мешавад. Дар усулҳои анъанавии оғозии монанди обравӣ, намнокии баланди хок ва ҳаво дар атрофи решаҳо заминаи муносиб барои пуршудани патогенҳо фароҳам меорад. Аммо бо ҷорӣ кардани <strong>оғозиқатра</strong> ва <strong>навари тиб</strong>, метавон намнокӣ-ро дақиқ дар минтақаи решагӣ марказӣ намуд ва минтақаҳои ғайрирешагиро хушк нигоҳ дошт, ки ин боиси камшавии зоҳиршудаи бемориҳои фитофтора ва тифус мегарданд.</p>\n<p>Дар ин мақола, ҷузъиёти техникии идоракунии зараррасонҳо ва бемориҳо дар парвариши пиёзонҳо бо фокус ба системаҳои навии оғозиро баррасӣ мекунем, то ки деҳқонҳо бо нигоҳ доштани саломати растаниҳо, аз манфиатҳои дар об ва энергия талофоткунии самаранокӣ файда бароранд.</p>\n\n<h2>Таъсири оғозиқатра бар камшавии бемориҳои занбӯрӣ</h2>\n<h3>Коррабарии рутубати назарии и пешгирӣ аз барги барҳои чӯлопӣ</h3>\n<p>Яке аз мушкилоти оммавӣ дар хушкакӣ бемориҳои қорӣ-баргӣ ба монанди сурхӣ ва торикӣ мебошад, ки дар ҳаво намнок бо суръати баланд паҳн мешаванд. Системаҳои сипо-кушо ба воситаи кам кардани обнокӣ-гулдорӣ ва рутубати сатҳӣ, монеа барои ташкили тумён, ки омилҳои асосии интиқоли спораҳо мебошанд, мебошад. Бо истифода аз бозори абзорҳои банди обнокӣ, омилоти доимӣ ва якҳолӣ ҷойгир мекунӣ, ки ба решаҳо фишори осмотики майҳонӣ меорӣ ва аз пӯхтани реша аз сабаби баста бо об дар оянда пешгирӣ мекунад.</p>\n\n\n<h3>Корбарӣ бемории пӯхтани решаҳо ва пӯстӣ</h3>\n<p>Бемории пӯхтани решаҳо (Root Rot) дар хушкакӣ асосан аз сабаби рутубати баланди динамистикаи ҷойи таркиб ва нодидагирии кофҳи обнокӣ ба амал меояд. Дар обнокӣ сипо-кушо, нақшаёрии вақти обнокӣ нақши асосӣ мебозад. Бо кам кардани рақами маротибаҳо ва зиёд кардани ҳаҷми об дар ҳар маротиба, мо метавонем давраҳои хушк ва намнокро танзим кунем, то оксигенрасонӣ ба решаҳо нигоҳ дошта шавад. Инчунин, истифодаи банди банди обнокӣ бо диаметри хурдтарӣ, таъсирбахшӣ ба шиддати ҷараёни об ва паҳншавии якхелаи он дар тӯли хатҳо дорад, ки ба пешгирӣ аз ба асос овардани манбаъҳои обнокӣ дар атрофи лӯлаҳо кӯмак мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-پیازچه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های پیازچه با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation хушкакӣ</figcaption></figure>\n\n<h2>Пешгирии гаровҳои реша бо банди обнокӣ</h2>\n<h3>Кам кардани шумораи кӯрҳои сафед ва хокӣ</h3>\n<p>Гаровҳои реша ба монанди кӯрҳои сафед (Sciaridae) ва баъзе намудҳои нимадода дар хокҳои намнок ва бой аз моддаҳои омонӣ камтар фаъол мебошанд. Банди обнокӣ бо ба вуҷуд овардани профили рутубатии тағйирёбанда дар чуқурӣ, боиси мешавад, ки решаҳои хушкакӣ ба самти рутубатҳои марказӣ рушд кунанд ва на рутубатҳои паҳншуда. Ин марказгарии реша, муқовимати растаниро нисбат ба таҳаммuli нимадода зиёд мекунад. Барои корбарии беҳтар, мо метавонем <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори боби тилби дар як ҳектар</a> Истиноди истеъмолкунӣ, ки чиззҳои зиёди растаниҳо, ки худ як омили ҷамъшавии намнокӣ ва ҷазби ҳашароти зараровар аст, кам шавад.</p>\n\n<h3>Идоракунии тилби сафед ва мушҳои хурд</h3>\n<p>Тилби сафед (Whitefly) ва мушҳои хурд ба растаниҳое, ки пӯшониши пурра ва намнокии ҳавоии баланд доранд, майланд. Бо нигоҳдоштани фазои кушода байни сатҳҳо ва истифодаи системаҳои обёрӣ маҳаллӣ, имкони аэратсияи беҳтар ва кам кардани намнокии нисбии сатҳи баргҳо фароҳам оварда мешавад. Дар системаҳои маҳкам ё шубҳаҳо, ки навар тиб истифода мешавад, аз филтрҳои микроантипаша ва бобҳои часпандаи зард истифода кардан мумкин аст, ки дар паҳлуди идоракуни дақиқ намнокӣ, суръати зиндамонии ҳашароти зарароварро ба ҳадди ақалл мерасонад.</p>\n\n\n<h2>Нуқтаҳои амалӣ барои беҳтар кардани системаи обёрӣ ва соҳаи растаниҳо</h2>\n<h3>Танзими фишор ва дебит дар системаи қатрагӣ</h3>\n<p>Барои парвариши тилби, танзими дебитҳои мувофиқ қатрагӣ ҳаётии аст. Дебитҳои тавсияшуда одатан байни 2 то 4 литр дар соат аст, ки вобаста ба намуди хок ва шароити абҳавот тағйир меёбад. Истифодаи навар тиб бо диаметри 16 то 20 миллиметр, тақсимоти беҳтарро, махсусан дар боғҳо ё заминҳои кушодаи тилби фароҳам меорад. Тавсия дода мешавад, ки ҳар 4 то 6 ҳафта як бор дебитҳои наварҳоро дубора санҷид, то аз гирифтани сӯрохиҳои микропорт аз сабаби ҷамъшавии намакҳо ё моддаҳои органикӣ пешгирӣ карда шавад.</p>\n\n<h3>Истифодаи обёрӣ бо филтр ва шуруъӣ</h3>\n<p>Яке аз бешумҳои асосии обори булқулавӣ, имконияти <strong>фильтрасияи дақиқ</strong> ва дарҷаи мустақими моддаҳои кимиёвӣ ё биологӣ ба реша мебошад. Барои назорати бемориҳои бактериявӣ, метавон аз антибиотикҳои руҷӯи кўшодӣ истифода бард, ки тавассути системаи булқулави Ҳе ҷиҳати реша ирсол мешаванд ва саҳби ояндотар аз ҳашаракзанки дулӣ доранд. Инчунин, дарҷаи мустақими моддаҳои беҳбудкунандаи хок, ба монанди кислотаҳои гумикӣ, тавассути навори тиб, саломатии реша ва муқовимати умумии обӣ зидди зарарҳои муҳити зистро зиёд мекунад. таҳқиқот <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b3%d8%a8%d8%b2%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/"> миқдори ғализи сабзавот дар гектар</a> намоён аст, ки саломатии реша мустақиман бо ҳосили охирини маҳсул алоқаманд аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-پیازچه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های پیازچه با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation пиёз</figcaption></figure>\n\n<h3>барорири ҳунарнамои обнори бар асоси маълумотҳои ҳавошиносӣ</h3>\n<p>истифодаи истгоҳҳои микроҳавошинос барои сабти ҳарорати кувва, намӣи нисбӣ ва намии хок, имкони иҷрои дақиқро фароҳам меорад <strong>Ориёнтирӣ</strong> ро таъмин мекунад. Дар рӯзҳои гарм ва намнок, бояд шумораи боркунӣ кам карда шавад, то намнокӣи нисбӣ зиёд нашавад. Баръакс, дар рӯзҳои хушк ва сард, зиёд кардани ҳаҷми боркунӣ барои нигоҳ доштани намнокӣи решаҳо зарур аст. Ин мувозинат, калиди пешгирии бемориҳои қарзӣ мебошад.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё боркунӣ бо нуқтагӣ нақши маҳвишҳои кимиёвиро барои идоракунии зараррасонҳо метавонад иваз кунад?</h3>\n<p>Не, боркунӣ бо нуқтагӣ ба таври мустақим зараррасонҳоро нест намекунанд, вай шароити муҳитро тағйир медиҳад, то паҳншавии зараррасонҳо ва бемориҳо кам карда шавад. Ин усул ҳамчун андозаҳои пешгирикунӣ ва иловагӣ барои идоракунии воҳиди зараррасонҳо (IPM) амал мекунад ва лозимияти маҳвишҳоеро ба дили кам шудани шиддати паҳншавӣ, кам мекунад.</p>\n\n<h3>Беҳтарин нӯъи филтр барои нуқтагинӣ дар парвариши бодаҳо чӣ аст?</h3>\n<p>Барои бодаҳо, ки решаҳои ҳассос доранд, истифодаи филтрҳои дискуӣ ё шабакавӣ бо андозаи зарраҳои 120 то 200 микрон тавсия дода мешавад. Филтрҳои ғӯршӣ низ дар системаҳои соддатар баста меоянд, вай дар истифодаи умури тӯлоӣ бо нуқтагинӣ, филтрҳои шабакавӣ аз рӯи пайдарпасӣ ва хароҷоти нигоҳубин иқтисодитар мебошанд.</p>\n\n<h3>Чӣ тавр қатъшавии нуқтагиниро ба дили шудаки дар об мавҷуданд бозгардонӣ?</h3>\n<p>Барои пешгирӣ аз хӯршиши система бо ҷамъшавии иштиҳоҳо, тавсия дода мешавад, ки аз об бо EC камтар аз 2 деси-сион дар сантиметр истифода баред. Инчунин, шустани муқаррарии система бо маҳлули кислотаи ситратӣ ё кислотаи ситрат ва танзими шуҷи муносиби хатҳо ба хориҷ шудани ҷамъшавиҳо кӯмак мерасонад. Истифодаи нӯри обёрӣ дар Насерия метавонад дар интихоби таҷҳизот барои обҳои сахт кӯмакрасон бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-پیازچه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های پیازچه با آبیاری قطره‌ای - تصویر 3"/><figcaption>ҳашарот ва бемориҳои буғҳо обёрӣ нӯрӣ пиёзча</figcaption></figure>\n\n<h2>Хулоса: ояндапешбинӣ дар идоракунии ҳашаротҳо барои пиёзча</h2>\n<p>гузариш аз обёрии анъанавӣ ба <strong>обёрии нӯрӣ ва нӯрии шифофӣ</strong>як тағйири парадигма дар кишоварзии дақиқи пиёзча аст. Ин технологияҳо бо таваҷҷӯҳ ба идоракунии тарк, на танҳо манбаҳои обро ҳифз мекунанд, балки тавассути коҳиши хатари бемориҳои қашқарӣ ва бактериявӣ мустақиман ба деҳқон кӯмак мерасонанд, то маҳсулоти солтимтар ва бо қудрати зиёда гиришта бошад. Барои беҳтарсозии самаранокӣ, фаҳмиши мутақобилаи ҳашаротҳо ва тағйироти муҳити хок зарурӣ аст. Риояи принсипҳои идоракунии якҷояи ҳашаротҳо ва истифодаи ғафтаронаи системаҳои обёрӣ кафолати устуворӣ ва самаранокии кишти пиёзча бошад.</p>\n<p>Барои фаҳмиши бештар оид ба миқдори истеҳсошуда ва оптимизатсияи манбаъҳо, мақолаҳои алоқамандро таҳқиқ кунед <a href="https://navar-abyari.ir/onion-yield-per-hectare-increase-tonnage-profitability/">афзоиши ҳосили пиёз дар гектар</a> Он инчунин ба шумо беназоирае кушодтарро дар бораи иқтисодиёти мулки кишоварӣ пешкаш карда метавонад.</p>\n\n<p><strong>Мавзӯъҳои пайваста:</strong> <a href="https://navar-abyari.ir/%d8%b4%d8%b1%d9%8a%d8%b7-%d8%a7%d9%84%d8%b1%d9%8a-%d8%a8%d8%a7%d9%84%d8%aa%d9%86%d9%82%d9%8a%d8%b7-%d9%81%d9%8a-%da%a9%d8%b1%da%a9%d9%88%da%a9/">Қабатҳои обёрӣ бо монғаронишӣ дар Кӯртӯкӯй: ҳалли устувори кишоварӣ</a></p>','Муборат ба зарароварон ва бемориҳои боқаро дар системаи обёрӣи қатрагӣ: Раҳнамои комил','Сабии булбулӣ ва шитобӣ абзорҳои муҳим барои идоракунии намӣ ва кам кардани паҳн шудани бемориҳои занбоорӣ ва бактериявӣ дар саразон мебошанд. Дар ин мақола, чораҳои амалӣ барои пешгирии зараррасонандагон ва бемориҳо бо истифода аз ин технологияҳо муҳокам карда мешаванд.','publish','closed','closed','moborat-ba-zararovaron-baqaro-obori-qatrakii',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
