INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل عملي للفلاحين العراقيين حول كيفية إدارة الآفات والأمراض في محاصيل اللفت باستخدام أنظمة الري بالتنقيط والخطي (AFPT) لتعزيز الإنتاجية والحد من الضياع.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
